function getEvents(supabase, userId) {
  participations = select event_id, role from event_participants where user_id=userId
  roleMap = new Map(participations.map(p => [p.event_id, p.role]))
  events = select * from events where id in eventIds
  return events.map(e => ({ event: toEventFromRowWithCount(e), role: roleMap.get(e.id) ?? 'participant' }))
}

