1. components/participant-count-realtime.tsx (Client Component):
   'use client';
   const [count, setCount] = useState(initialCount);
   useEffect(() => {
     const supabase = createClient(); // lib/supabase/client.ts
     const channel = supabase.channel(`event_participants_${eventId}`)
       .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'event_participants', filter: `event_id=eq.${eventId}` }, () => { setCount(c => c+1); router.refresh(); })
       .on('postgres_changes', { event: 'DELETE', schema: 'public', table: 'event_participants', filter: `event_id=eq.${eventId}` }, () => { setCount(c => c-1); router.refresh(); })
       .subscribe();
     return () => { supabase.removeChannel(channel); };
   }, [eventId]);
